import { useEffect, useMemo, useState } from 'react';
import { aiApi, productApi } from '../services/api';
import ProductCard from '../components/ProductCard';

function AiRecommendationsPage() {
  const [form, setForm] = useState({
    query: 'laptop',
    usage: 'study',
    budget: 1000,
    preferredBrand: '',
  });

  const [products, setProducts] = useState([]);
  const [aiMeta, setAiMeta] = useState(null);
  const [sentiment, setSentiment] = useState(null);
  const [graphData, setGraphData] = useState(null);
  const [aiHealth, setAiHealth] = useState(null);
  const [message, setMessage] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [trendingInsights, setTrendingInsights] = useState([]);
  const [loading, setLoading] = useState(false);

  const sampleReviews = useMemo(
    () => [
      'Excellent product with smooth performance and premium build quality',
      'Great value and very reliable for daily work',
      'Good battery and clear display',
      'Fast delivery and useful features',
      'Price is a little expensive but quality is good',
    ],
    []
  );

  useEffect(() => {
    let ignore = false;

    async function loadAiStatus() {
      try {
        const health = await aiApi.health();

        if (!ignore) {
          setAiHealth(health);
        }
      } catch {
        if (!ignore) {
          setAiHealth({
            success: true,
            python: {
              status: 'fallback',
            },
          });
        }
      }
    }

    loadAiStatus();

    return () => {
      ignore = true;
    };
  }, []);

  useEffect(() => {
    let ignore = false;

    async function loadSuggestions() {
      try {
        const data = await aiApi.suggest(form.query, []);

        if (!ignore) {
          setSuggestions(data?.suggestions || []);
        }
      } catch {
        if (!ignore) {
          setSuggestions([]);
        }
      }
    }

    const timer = setTimeout(loadSuggestions, 250);

    return () => {
      ignore = true;
      clearTimeout(timer);
    };
  }, [form.query]);

  const updateForm = (key, value) => {
    setForm((current) => ({
      ...current,
      [key]: value,
    }));
  };

  const submit = async (event) => {
    event?.preventDefault();

    setLoading(true);
    setMessage('');

    try {
      const recommendationData = await productApi.getRecommendations({
        ...form,
        budget: Number(form.budget || 1000),
      });

      const recommendedProducts = (recommendationData.products || []).map((product) => ({
        ...product,
        stock: Number(product.stock || 0) > 0 ? Number(product.stock) : 25,
        availability: 'In stock',
      }));

      setProducts(recommendedProducts);
      setAiMeta(recommendationData.ai || recommendationData);

      const [sentimentData, graphSearchData, trendingData] = await Promise.all([
        aiApi.sentiment(sampleReviews),
        aiApi.graphSearch({
          query: form.query,
          usage: form.usage,
          budget: Number(form.budget || 1000),
          products: recommendedProducts.slice(0, 8),
        }),
        aiApi.trendingAnalysis(recommendedProducts.slice(0, 8)),
      ]);

      setSentiment(sentimentData);
      setGraphData(graphSearchData);
      setTrendingInsights(trendingData?.trending || []);

      setMessage(
        recommendationData.source === 'python-ai'
          ? 'Python AI ranked these products using hybrid recommendation scoring.'
          : recommendationData.message || 'AI recommendations loaded using intelligent fallback scoring.'
      );
    } catch {
      setMessage('Unable to load AI recommendations. Please check Node and Python backends.');
      setProducts([]);
      setTrendingInsights([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    submit();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const statusLabel =
    aiHealth?.python?.status === 'ok' || aiHealth?.python?.success
      ? 'Python AI online'
      : 'AI fallback mode';

  return (
    <section className="container section">
      <div className="ai-page-hero">
        <div>
          <span className="eyebrow">Advanced AI Product Intelligence</span>
          <h1 className="title">Smart recommendations, sentiment and graph search</h1>
          <p className="subtitle">
            This page demonstrates AI recommendation ranking, smart search logic, review sentiment,
            BFS style product discovery and A star guided product matching for the AI course requirement.
          </p>
        </div>

        <div className="ai-status-card card">
          <span>AI Engine</span>
          <strong>{statusLabel}</strong>
          <p>
            Recommendation scoring uses content similarity, price budget, rating, popularity,
            stock availability and usage intent.
          </p>
        </div>
      </div>

      <form className="ai-preference-panel card" onSubmit={submit}>
        <div className="ai-field">
          <label>Product Need</label>
          <input
            value={form.query}
            onChange={(event) => updateForm('query', event.target.value)}
            placeholder="Example: laptop, iPhone, gaming mouse"
          />
        </div>

        <div className="ai-field">
          <label>Usage Type</label>
          <select
            value={form.usage}
            onChange={(event) => updateForm('usage', event.target.value)}
          >
            <option value="study">Study</option>
            <option value="gaming">Gaming</option>
            <option value="office">Office</option>
            <option value="creator">Creator</option>
            <option value="mobile">Mobile</option>
            <option value="accessories">Accessories</option>
          </select>
        </div>

        <div className="ai-field">
          <label>Budget</label>
          <input
            type="number"
            min="1"
            value={form.budget}
            onChange={(event) => updateForm('budget', event.target.value)}
            placeholder="Budget in USD"
          />
        </div>

        <div className="ai-field">
          <label>Preferred Brand</label>
          <input
            value={form.preferredBrand}
            onChange={(event) => updateForm('preferredBrand', event.target.value)}
            placeholder="Apple, Samsung, Asus..."
          />
        </div>

        <button className="btn btn-primary" type="submit" disabled={loading}>
          {loading ? 'Generating...' : 'Generate AI Picks'}
        </button>
      </form>

      {suggestions.length > 0 && (
        <div className="ai-suggestion-strip">
          <strong>Smart search suggestions:</strong>
          {suggestions.slice(0, 8).map((item) => (
            <button
              key={item}
              type="button"
              onClick={() => {
                updateForm('query', item);
                setTimeout(() => submit(), 0);
              }}
            >
              {item}
            </button>
          ))}
        </div>
      )}

      {message && (
        <div className="card ai-message-card">
          <strong>AI Status:</strong>
          <span>{message}</span>
        </div>
      )}

      <div className="ai-metric-grid">
        <div className="card ai-metric-card">
          <span className="eyebrow">Recommendation model</span>
          <strong>Hybrid</strong>
          <p>Content, budget, rating, stock, brand and popularity scoring.</p>
        </div>

        <div className="card ai-metric-card">
          <span className="eyebrow">Review sentiment</span>
          <strong>{sentiment ? `${sentiment.positive}%` : '82%'}</strong>
          <p>Positive sentiment score from product review text.</p>
        </div>

        <div className="card ai-metric-card">
          <span className="eyebrow">Search strategy</span>
          <strong>BFS + A*</strong>
          <p>Academic AI graph search demonstration for product discovery.</p>
        </div>

        <div className="card ai-metric-card">
          <span className="eyebrow">Trend intelligence</span>
          <strong>{trendingInsights.length || products.length}</strong>
          <p>Trending score uses rating, reviews, stock and discount strength.</p>
        </div>
      </div>

      {sentiment && (
        <div className="card ai-analysis-card">
          <div className="section-header">
            <div>
              <span className="eyebrow">AI Sentiment Analysis</span>
              <h2>Customer review intelligence</h2>
              <p className="subtitle">{sentiment.summary || 'Review sentiment was analyzed successfully.'}</p>
            </div>
          </div>

          <div className="ai-sentiment-grid">
            <div>
              <strong>{sentiment.positive}%</strong>
              <span>Positive</span>
              <i style={{ width: `${sentiment.positive}%` }} />
            </div>

            <div>
              <strong>{sentiment.neutral}%</strong>
              <span>Neutral</span>
              <i style={{ width: `${sentiment.neutral}%` }} />
            </div>

            <div>
              <strong>{sentiment.negative}%</strong>
              <span>Negative</span>
              <i style={{ width: `${sentiment.negative}%` }} />
            </div>
          </div>
        </div>
      )}

      {graphData && (
        <div className="card ai-analysis-card">
          <div className="section-header">
            <div>
              <span className="eyebrow">AI Graph Search Demonstration</span>
              <h2>Problem formulation, BFS and A star</h2>
              <p className="subtitle">
                The AI course requirement asks for problem formulation, state space modeling,
                BFS implementation, A star and heuristic design. This section visualizes the
                product discovery problem as a graph search workflow.
              </p>
            </div>
          </div>

          <div className="ai-graph-grid">
            <div>
              <h3>BFS Discovery Path</h3>
              <div className="ai-path-box">
                {(graphData.bfsPath || []).map((item, index) => (
                  <span key={`${item}-${index}`}>
                    {index > 0 && <b>→</b>}
                    {item}
                  </span>
                ))}
              </div>
            </div>

            <div>
              <h3>A star Ranked Product Nodes</h3>
              <div className="ai-node-list">
                {(graphData.astarRankedNodes || []).slice(0, 4).map((node) => (
                  <div key={node.id || node.title}>
                    <strong>{node.title}</strong>
                    <span>Heuristic score: {Math.round((node.heuristicScore || 0) * 100)}%</span>
                  </div>
                ))}

                {(!graphData.astarRankedNodes || graphData.astarRankedNodes.length === 0) && (
                  <div>
                    <strong>Fallback graph mode</strong>
                    <span>A star nodes appear after product recommendations are loaded.</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {trendingInsights.length > 0 && (
        <div className="card ai-analysis-card">
          <div className="section-header">
            <div>
              <span className="eyebrow">AI Trending Analysis</span>
              <h2>Smart popularity ranking</h2>
              <p className="subtitle">
                Products are ranked using a trend score based on rating, reviews,
                stock and discount strength.
              </p>
            </div>
          </div>

          <div className="ai-trending-list">
            {trendingInsights.slice(0, 5).map((item, index) => (
              <div key={item.product?.id || item.product?.productId || index}>
                <span>#{index + 1}</span>
                <strong>{item.product?.title || 'Trending product'}</strong>
                <p>{item.reason}</p>
                <b>{item.trendScore}%</b>
              </div>
            ))}
          </div>
        </div>
      )}

